"""Tiny wc. Usage: python wc.py [--lines] [--words] [--chars] [--top N] FILE"""
import argparse
import sys


def count(text):
    return {"lines": len(text.splitlines()), "words": len(text.split())}


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--lines", action="store_true")
    ap.add_argument("--words", action="store_true")
    ap.add_argument("--chars", action="store_true")
    ap.add_argument("--top", type=int, default=None)
    a = ap.parse_args(argv)
    with open(a.file) as f:
        text = f.read()
    c = count(text)
    selected = [k for k in ("lines", "words", "chars") if getattr(a, k)]
    if a.top is not None:
        selected = ["top"]
    for k in selected:
        if k == "top":
            words = {}
            for word in text.split():
                words[word] = words.get(word, 0) + 1
            for word, n in sorted(words.items(), key=lambda item: item[1], reverse=True)[:a.top]:
                print(f"{word} {n}")
        else:
            print(f"{k} {c[k]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
